INSERT INTO _fields_wd5_plan (site_id, column_name, old_value, new_value, change_key, reason, evidence) VALUES
    ('a25bcd91-5122-452f-9a4c-87377012c26c'::uuid, 'period_name', '1500 - 500 BC', '4500 - 3000 BC', 'fields-wd5-2026-10-25p-s007-rollback:a25bcd91-5122-452f-9a4c-87377012c26c:period_name', 'rollback of fields-wd5-2026-10-25p-s007: period_name ''4500 - 3000 BC'' restored on Castle Goff', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(-800) = ''1500 - 500 BC''"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}, {"source": "WD5 decision (counted, round 0, field_researcher:wd5-r0-b0022)", "decision": "replace", "status": "MISSING", "reasoning": "iWalk Cornwall calls Castle Goff a small Iron Age hillfort; the Gatehouse Gazetteer (quoting PastScape: an IA/RB round) holds an Iron Age round as the start, with a possible medieval ringwork reuse that no source proves. Never excavated, so the period name is the date; the stored -4000 had no source.", "value_page": null, "model": "anthropic/claude-sonnet-5-5 (Claude Code agent)", "adversarial": {"answered_by": "adversarial:adv-r1-b0002", "model": "anthropic/claude-sonnet-5-5 (Claude Code agent)", "reason": "Historic England schedules it as an Iron Age/Romano-British round (PastScape), but Gatehouse finds a classic ringwork-and-bailey form, the site is unexcavated and undated, and Wikipedia says rounds run from the late Iron Age to the early post-Roman period, which does not support the Iron Age start of -800.", "round": 1, "verdict": "unclear"}, "owner": {"at": "2026-10-25T07:49:50+00:00", "decision": "D69", "reason": "owner 2026-10-25 (D69): write the researcher''s value with its found quote for a cell the re-check held as unclear"}}]'::jsonb),
